RSpec.describe "Reservation prepare access" do
  include_context "timekeeping entry writes"

  it "refuses prepare from no token, a user token, a service without prepare and another company's service, writing nothing" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    user = timekeeping_arrange.user(company:, role: "owner")
    entry_id = timekeeping_arrange.entry(company:, user:, project: timekeeping_arrange.project(company:))
    all_routes = %w[prepare commit abort mark_billed detach_entries]
    credentials = {
      nil => [401, "unauthorized"],
      # "An anonymous or user-delegated request never gets it."
      timekeeping_arrange.token_for(user) => [403, "forbidden"],
      timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: all_routes - ["prepare"]) => [403, "forbidden"],
      timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary", operations: all_routes) => [404, "not_found"]
    }
    counts = -> { [Reservation.count, InvoiceOperation.count, AuditEvent.count, OutboxSnapshot.count, IdempotencyReceipt.count] }
    before = counts.call

    credentials.each do |credential, (status, reason)|
      headers = { "Content-Type" => "application/json" }
      headers["Authorization"] = "Bearer #{credential}" if credential
      body = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation,
               "disposition" => "active", "entries" => [entry_id] }
      post "/v1/companies/#{company}/reservations/prepare", params: JSON.generate(body), headers: headers

      expect([response.status, response.parsed_body]).to eq([status, { "reason" => reason }])
    end
    expect(counts.call).to eq(before)
  end
end

