require "rails_helper"
require "webmock/rspec"

RSpec.describe "Entry writes carrying a service token" do
  include_context "timekeeping entry writes"

  it "refuses a user entry write whose note carries an unregistered company-bound service token and stores nothing" do
    company = timekeeping_arrange.company
    employee = timekeeping_arrange.user(company:, role: "employee")
    project = timekeeping_arrange.project(company:)
    now = Time.now.to_i
    # Minted here with the service secret and never registered as a held
    # credential, as a token the monolith minted for another request would be.
    service_token = JWT.encode({ typ: "timekeeping_service", sub: "invoice-boundary", company_id: company,
                                 operations: ["reservations.prepare", "invoices.mark_billed"], iat: now,
                                 exp: now + 60, jti: SecureRandom.uuid }, provider_service_token, "HS256")
    before = entry_write_counts
    body = { "project_id" => project, "work_date" => "2026-03-02", "duration" => 45.0,
             "note" => "see #{service_token} thanks", "source" => "manual", "source_metadata" => {} }
    headers = { "Content-Type" => "application/json", "Authorization" => "Bearer #{timekeeping_arrange.token_for(employee)}",
                "Ownership-Generation" => timekeeping_arrange.current_generation.to_s, "Idempotency-Key" => SecureRandom.uuid }

    post "/v1/companies/#{company}/entries", params: JSON.generate(body), headers: headers

    expect([response.status, response.parsed_body]).to eq([422, { "reason" => "credential_in_body" }])
    expect(response.body).not_to include(service_token)
    expect(entry_write_counts).to eq(before)
  end
end

require "rails_helper"
require "webmock/rspec"

RSpec.describe "Reservation operation ids across companies" do
  include_context "timekeeping entry writes"

  it "never commits or aborts another company's operation that reuses the same operation id" do
    company = timekeeping_arrange.company
    other_company = timekeeping_arrange.company
    all_routes = %w[prepare commit abort mark_billed detach_entries]
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: all_routes)
    other_service = timekeeping_arrange.service_identity(company: other_company, name: "invoice-boundary", operations: all_routes)
    entry_id = timekeeping_arrange.entry(company:, user: timekeeping_arrange.user(company:, role: "employee"),
                                         project: timekeeping_arrange.project(company:))
    operation_id = SecureRandom.uuid
    send_command = lambda do |company_id, credential, route, body|
      post "/v1/companies/#{company_id}/reservations/#{route}",
           params: JSON.generate({ "generation" => timekeeping_arrange.current_generation, "invoice_id" => 501,
                                   "operation_id" => operation_id }.merge(body)),
           headers: { "Content-Type" => "application/json", "Authorization" => "Bearer #{credential}" }
      response
    end
    expect(send_command.call(company, service, "prepare", { "disposition" => "active", "entries" => [entry_id] }).status).to eq(200)
    before = [Reservation.where(entry_id:).pluck(:state), AuditEvent.count, OutboxSnapshot.count, Entry.find(entry_id).version]

    # "Operation ids are unique only within a company."
    commit = send_command.call(other_company, other_service, "commit", {})
    abort = send_command.call(other_company, other_service, "abort", {})

    expect([commit.status, abort.status]).to eq([404, 404])
    expect([Reservation.where(entry_id:).pluck(:state), AuditEvent.count, OutboxSnapshot.count,
            Entry.find(entry_id).version]).to eq(before)
  end
end

RSpec.describe "Reservation request bodies" do
  include_context "timekeeping entry writes"

  it "answers a wrongly shaped body with invalid_request and a body holding a credential with credential_in_body, writing nothing" do
    company = timekeeping_arrange.company
    entry_id = timekeeping_arrange.entry(company:, user: timekeeping_arrange.user(company:, role: "employee"),
                                         project: timekeeping_arrange.project(company:))
    service = timekeeping_arrange.service_identity(company:, name: "invoice-boundary", operations: %w[prepare])
    held = timekeeping_arrange.held_credential("reporting")
    valid = { "invoice_id" => 501, "operation_id" => SecureRandom.uuid, "generation" => timekeeping_arrange.current_generation,
              "disposition" => "active", "entries" => [entry_id] }
    counts = -> { [Reservation.count, InvoiceOperation.count, AuditEvent.count, OutboxSnapshot.count, Entry.sum(:version)] }
    before = counts.call

    {
      JSON.generate(valid.merge("entries" => [entry_id, entry_id])) => [400, "invalid_request"],
      JSON.generate(valid.merge("operation_id" => "op-1")) => [400, "invalid_request"],
      "not json" => [400, "invalid_request"],
      JSON.generate(valid.merge("note" => held)) => [422, "credential_in_body"],
      JSON.generate(valid.merge("note" => service)) => [422, "credential_in_body"]
    }.each do |raw_body, (status, reason)|
      post "/v1/companies/#{company}/reservations/prepare", params: raw_body,
                                                            headers: { "Content-Type" => "application/json",
                                                                       "Authorization" => "Bearer #{service}" }

      expect([response.status, response.parsed_body]).to eq([status, { "reason" => reason }])
    end
    expect(counts.call).to eq(before)
  end
end
